def test_ampersand_escaped_before_angle_brackets():
    # If `&` is escaped last it re-escapes the ampersands introduced by
    # `&lt;`/`&gt;`, and the reader sees a literal `&lt;`.
    assert render("<b> & </b>") == "&lt;b&gt; &amp; &lt;/b&gt;"


def test_already_escaped_entity_is_escaped_again():
    # Input is text, not markup: a literal `&amp;` typed by a user must survive
    # as visible text rather than decoding back to a bare `&`.
    assert render("&amp;") == "&amp;amp;"


